        int length = scanner.nextInt();
        scanner.nextLine();
        String str = scanner.nextLine();

        int maxWordLength = 0;
        int bracketsCount = 0;
        boolean insideBracket = false;
        boolean inBracketWord = false;
        int currentWordLength = 0;
        int maxWordRecorded = 0;

        for (int index = 0; index < length; index++) {
