                if (insideBracket) {
                    inBracketWord = true;
                } else {
                    currentWordLength++;
                }
            }
        }
        if (currentWordLength > maxWordRecorded) {
            maxWordRecorded = currentWordLength;
        }
        System.out.println(maxWordRecorded + " " + bracketsCount);
    }
}
